class Solution:
    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        n = len(nums)
        ans = []

        for mask in range(1 << n):
            skip = False
            subset = []
            for i in range(n):
                if mask & (1 << i):
                    if i > 0 and nums[i] == nums[i - 1] and not (mask & (1 << (i - 1))):
                        skip = True
                        break
                    subset.append(nums[i])
            if not skip:
                ans.append(subset)

        return ans
